[
  {
    "key": "hubspot/access_token",
    "description": "HubSpot Private App access token (Private App mode, the default; https://developers.hubspot.com/docs/api/private-apps). Used by the agent's hubspot_* tools as a Bearer token; only api.hubapi.com is reachable. Not needed in OAuth mode."
  },
  {
    "key": "hubspot/auth_mode",
    "description": "Optional auth selector for the HubSpot extension. Set to 'oauth' to fetch tokens from the platform OAuth broker (provision per component-hubspot-ext/docs/oauth-setup.md); any other value or unset uses the Private App token."
  },
  {
    "key": "llm/deepseek",
    "description": "DeepSeek LLM API key for the agentic worker's reasoning loop."
  }
]
